// PATCH: release-plan covers local-only public-release readiness guidance and safety metadata.
func TestReleasePlanNoArgJSONReturnsSurfacesAndSafety(t *testing.T) {
	stdout, stderr, err := runCLIForDocsTest(t, "release", "plan", "--json")
	if err != nil {
		t.Fatalf("release plan --json returned error: %v", err)
	}
	if stderr != "" {
		t.Fatalf("release plan wrote stderr: %q", stderr)
	}

	var got releasePlanResponse
	if err := json.Unmarshal([]byte(stdout), &got); err != nil {
		t.Fatalf("release plan --json emitted invalid JSON: %v\n%s", err, stdout)
	}
	if got.Command != "release plan" {
		t.Fatalf("command = %q, want release plan", got.Command)
	}
	wantSurfaces := []string{"archives", "docs-support", "homebrew", "mcp", "naming", "npm", "signing", "all"}
	if strings.Join(got.AvailableSurfaces, ",") != strings.Join(wantSurfaces, ",") {
		t.Fatalf("available surfaces = %#v, want %#v", got.AvailableSurfaces, wantSurfaces)
	}
	if !got.Safety.GuidanceOnly || !got.Safety.LocalOnly || !got.Safety.NoSecretsRead || !got.Safety.NoPublishing {
		t.Fatalf("release plan should be local guidance without secrets or publishing: %#v", got.Safety)
	}
	if got.Safety.MakesAPICalls || got.Safety.CallsGitHub || got.Safety.CallsHomebrew || got.Safety.CallsNPM || got.Safety.SignsOrNotarizes || got.Safety.ExecutesMCP {
		t.Fatalf("release plan should not call external systems, sign, notarize, or execute MCP: %#v", got.Safety)
	}
}

func TestReleasePlanSurfacesIncludeRequiredRunbookData(t *testing.T) {
	tests := map[string][]string{
		"archives": {
			"make release-check",
			"make release-snapshot",
			"make clean",
		},
		"docs-support": {
			"straddle-pp-cli release plan docs-support --json",
			"straddle-pp-cli docs search straddle --source commands --json",
			"straddle-pp-cli smoke plan approval --json",
			"straddle-pp-cli credentials plan launch --json",
		},
		"homebrew": {
			"make release-check",
			"make release-snapshot",
		},
		"mcp": {
			"make package-readiness",
			"make release-snapshot",
		},
		"naming": {
			"straddle-pp-cli --help",
			"straddle-pp-cli about --json",
			"straddle-pp-cli release plan naming --json",
		},
		"npm": {
			"make release-check",
		},
		"signing": {
			"make release-check",
			"make release-snapshot",
		},
	}

	for surface, wantCommands := range tests {
		t.Run(surface, func(t *testing.T) {
			stdout, stderr, err := runCLIForDocsTest(t, "release", "plan", surface, "--json")
			if err != nil {
				t.Fatalf("release plan %s --json returned error: %v", surface, err)
			}
			if stderr != "" {
				t.Fatalf("release plan %s wrote stderr: %q", surface, stderr)
			}

			var got releasePlanResponse
			if err := json.Unmarshal([]byte(stdout), &got); err != nil {
				t.Fatalf("release plan %s --json emitted invalid JSON: %v\n%s", surface, err, stdout)
			}
			if got.Surface != surface || got.SurfacePlan == nil {
				t.Fatalf("expected %s surface plan, got %#v", surface, got)
			}
			for _, want := range wantCommands {
				if !containsString(got.SurfacePlan.LocalProofCommands, want) {
					t.Fatalf("%s surface commands = %#v, want %q", surface, got.SurfacePlan.LocalProofCommands, want)
				}
			}
			if len(got.SurfacePlan.PublicArtifactSurfaces) == 0 {
				t.Fatalf("%s surface should include public artifact surfaces", surface)
			}
			if len(got.SurfacePlan.RequiredFutureApprovals) == 0 {
				t.Fatalf("%s surface should include required future approvals", surface)
			}
			if len(got.SurfacePlan.Blockers) == 0 {
				t.Fatalf("%s surface should include blockers", surface)
			}
			if strings.Contains(stdout, "STRADDLE_TOKEN=") || strings.Contains(stdout, "Bearer ") {
				t.Fatalf("release plan should not emit token literals or bearer examples:\n%s", stdout)
			}
		})
	}
}

func TestReleasePlanSpecialSurfacesStayHonest(t *testing.T) {
	stdout, _, err := runCLIForDocsTest(t, "release", "plan", "signing", "--json")
	if err != nil {
		t.Fatalf("release plan signing --json returned error: %v", err)
	}
	if !strings.Contains(stdout, "signing and notarization decision is unresolved") {
		t.Fatalf("signing surface should call out unresolved signing and notarization decision:\n%s", stdout)
	}
	if !strings.Contains(stdout, "required before public macOS distribution") {
		t.Fatalf("signing surface should call out public macOS distribution requirement:\n%s", stdout)
	}

	stdout, _, err = runCLIForDocsTest(t, "release", "plan", "mcp", "--json")
	if err != nil {
		t.Fatalf("release plan mcp --json returned error: %v", err)
	}
	if !strings.Contains(stdout, "MCP sibling exists") || !strings.Contains(stdout, "desktop MCP bundle") {
		t.Fatalf("mcp surface should distinguish archived sibling from future desktop bundle:\n%s", stdout)
	}

	stdout, _, err = runCLIForDocsTest(t, "release", "plan", "npm", "--json")
	if err != nil {
		t.Fatalf("release plan npm --json returned error: %v", err)
	}
	if !strings.Contains(stdout, "No npm or npx path exists yet") {
		t.Fatalf("npm surface should say no npm or npx path exists yet:\n%s", stdout)
	}

	stdout, _, err = runCLIForDocsTest(t, "release", "plan", "naming", "--json")
	if err != nil {
		t.Fatalf("release plan naming --json returned error: %v", err)
	}
	if !strings.Contains(stdout, "current preview command is straddle-pp-cli") {
		t.Fatalf("naming surface should state the current preview command:\n%s", stdout)
	}
	if !strings.Contains(stdout, "public straddle command/binary is not approved yet") {
		t.Fatalf("naming surface should state public straddle is not approved:\n%s", stdout)
	}

	stdout, _, err = runCLIForDocsTest(t, "release", "plan", "docs-support", "--json")
	if err != nil {
		t.Fatalf("release plan docs-support --json returned error: %v", err)
	}
	if !strings.Contains(stdout, "Public docs and support are not approved yet") {
		t.Fatalf("docs-support surface should say public docs and support are not approved yet:\n%s", stdout)
	}
	if !strings.Contains(stdout, "must not imply workflow execution, production readiness, or replacement of public straddle") {
		t.Fatalf("docs-support surface should not imply public launch or public straddle replacement:\n%s", stdout)
	}
	if strings.Contains(stdout, "public launch is approved") || strings.Contains(stdout, "production ready") || strings.Contains(stdout, "replaces public straddle") {
		t.Fatalf("docs-support surface should not imply approved launch, production readiness, or public straddle replacement:\n%s", stdout)
	}
}

